-- Knowledge model v2: grants_rls. See docs/knowledge-model/FINAL-RECOMMENDATION.md.
begin;
set local lock_timeout = '15s';

-- Scope new foreign keys by tenant, including child tables whose abbreviated design used id alone.
do $$ declare t text; r record; target text; begin
 foreach t in array array['taxonomy.relationship_kind','temporal.stream_kind','temporal.event_kind','content.document_type','content.transformation_kind','evidence.search_provider','evidence.capture_method','corpus.license','corpus.distribution_kind','corpus.entity','corpus.entity_alias','corpus.entity_identifier','corpus.entity_merge','corpus.person','corpus.organization','corpus.product','corpus.product_version','corpus.product_feature','corpus.ai_model','corpus.ai_model_version','corpus.model_offering','corpus.technique','corpus.dataset','corpus.benchmark','corpus.benchmark_run','corpus.repository','corpus.library','corpus.library_release','corpus.mcp_server','corpus.agent_skill','corpus.ai_protocol','corpus.ai_protocol_version','corpus.ai_protocol_feature','corpus.paper','corpus.story','corpus.case_study','corpus.concept','corpus.funding_round','corpus.corporate_transaction','corpus.registry','corpus.security_advisory','corpus.compute_device','corpus.compute_offering','corpus.media_platform','corpus.media_channel','corpus.event_series','corpus.industry_event','corpus.media_series','corpus.media_work','corpus.talk','corpus.repository_revision','corpus.repository_module','corpus.repository_file','corpus.ai_model_version_spec','corpus.mcp_server_surface','corpus.registry_listing','corpus.relationship','corpus.media_appearance','temporal.knowledge_head','temporal.knowledge_batch','temporal.extent','temporal.stream','temporal.event','temporal.event_occurrence','temporal.segment','evidence.source_query','evidence.provider_result','evidence.source_encounter','evidence.extraction_run','evidence.extraction_record','evidence.attribution','evidence.claim_subject','evidence.claim_record','evidence.segment_support','content.document_about_entity','content.document_summary','content.document_summary_source','knowledge.record','knowledge.technical_problem','knowledge.solution_pattern','knowledge.advanced_usage_pattern','knowledge.implementation_example','knowledge.failure_mode','knowledge.benchmark_result','knowledge.compatibility_constraint','knowledge.operational_practice','knowledge.security_consideration','knowledge.record_entity_link','retrieval.projection_target','retrieval.chunk_entity_mention','retrieval.chunk_claim_link','retrieval.chunk_relationship_evidence','ranking.metric_definition','ranking.metric_definition_version','ranking.metric_observation','ranking.feature_value','ranking.ranking_result','staging.candidate','staging.identity_match','staging.resolution_decision','staging.vetting_decision'] loop
  if exists(select 1 from pg_attribute where attrelid=t::regclass and attname='tenant_id' and not attisdropped) then
   execute format('alter table %s enable row level security',t);
   execute format('create policy km_tenant_access on %s for all to executor_service,pipeline_agent,verifier_agent,control_plane using(tenant_id=util.current_tenant_id()) with check(tenant_id=util.current_tenant_id())',t);
   if exists(select 1 from pg_attribute where attrelid=t::regclass and attname='id' and not attisdropped) and not exists(select 1 from pg_constraint where conrelid=t::regclass and contype='u' and pg_get_constraintdef(oid)='UNIQUE (tenant_id, id)') then execute format('alter table %s add unique(tenant_id,id)',t); end if;
  end if;
 end loop;
 foreach t in array array['taxonomy.relationship_kind','temporal.stream_kind','temporal.event_kind','content.document_type','content.transformation_kind','evidence.search_provider','evidence.capture_method','corpus.license','corpus.distribution_kind','corpus.entity','corpus.entity_alias','corpus.entity_identifier','corpus.entity_merge','corpus.person','corpus.organization','corpus.product','corpus.product_version','corpus.product_feature','corpus.ai_model','corpus.ai_model_version','corpus.model_offering','corpus.technique','corpus.dataset','corpus.benchmark','corpus.benchmark_run','corpus.repository','corpus.library','corpus.library_release','corpus.mcp_server','corpus.agent_skill','corpus.ai_protocol','corpus.ai_protocol_version','corpus.ai_protocol_feature','corpus.paper','corpus.story','corpus.case_study','corpus.concept','corpus.funding_round','corpus.corporate_transaction','corpus.registry','corpus.security_advisory','corpus.compute_device','corpus.compute_offering','corpus.media_platform','corpus.media_channel','corpus.event_series','corpus.industry_event','corpus.media_series','corpus.media_work','corpus.talk','corpus.repository_revision','corpus.repository_module','corpus.repository_file','corpus.ai_model_version_spec','corpus.mcp_server_surface','corpus.registry_listing','corpus.relationship','corpus.media_appearance','temporal.knowledge_head','temporal.knowledge_batch','temporal.extent','temporal.stream','temporal.event','temporal.event_occurrence','temporal.segment','evidence.source_query','evidence.provider_result','evidence.source_encounter','evidence.extraction_run','evidence.extraction_record','evidence.attribution','evidence.claim_subject','evidence.claim_record','evidence.segment_support','content.document_about_entity','content.document_summary','content.document_summary_source','knowledge.record','knowledge.technical_problem','knowledge.solution_pattern','knowledge.advanced_usage_pattern','knowledge.implementation_example','knowledge.failure_mode','knowledge.benchmark_result','knowledge.compatibility_constraint','knowledge.operational_practice','knowledge.security_consideration','knowledge.record_entity_link','retrieval.projection_target','retrieval.chunk_entity_mention','retrieval.chunk_claim_link','retrieval.chunk_relationship_evidence','ranking.metric_definition','ranking.metric_definition_version','ranking.metric_observation','ranking.feature_value','ranking.ranking_result','staging.candidate','staging.identity_match','staging.resolution_decision','staging.vetting_decision'] loop
  for r in select c.oid,c.confrelid,c.conrelid,a.attname column_name from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=c.conkey[1] where c.conrelid=t::regclass and c.contype='f' and cardinality(c.conkey)=1 and exists(select 1 from pg_attribute where attrelid=c.conrelid and attname='tenant_id' and not attisdropped) and exists(select 1 from pg_constraint u where u.conrelid=c.confrelid and u.contype='u' and pg_get_constraintdef(u.oid)='UNIQUE (tenant_id, id)') loop
   execute format('alter table %s add foreign key(tenant_id,%I) references %s(tenant_id,id) deferrable initially deferred',r.conrelid::regclass,r.column_name,r.confrelid::regclass);
  end loop;
 end loop;
end $$;
