do $$ declare r record; begin
 for r in select p.oid::regprocedure signature from pg_proc p where p.pronamespace='api'::regnamespace and p.proname in ('resolve_entity','entity_at','relationships','entity_card','entity_timeline','what_changed','summary_evidence','evidence_packet','hybrid_knowledge_search_1536','leaderboard') loop
 execute format('revoke all on function %s from public,anon',r.signature);
 execute format('grant execute on function %s to app_reader,authenticated,executor_service,pipeline_agent,verifier_agent,control_plane,service_role',r.signature);
 end loop;
end $$;
