grant usage on schema api to app_reader,authenticated;


create function corpus.check_receipt_tenant() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from orchestration.operation_receipt r join orchestration.operation_intent i on i.id=r.intent_id where r.id=new.created_by_receipt_id and i.tenant_id=new.tenant_id) then raise exception 'entity/record receipt tenant mismatch'; end if;
 return new;
end $$;
create trigger entity_receipt_tenant before insert or update on corpus.entity for each row execute function corpus.check_receipt_tenant();
create trigger record_receipt_tenant before insert or update on knowledge.record for each row execute function corpus.check_receipt_tenant();
create function corpus.check_repository_lineage() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from corpus.repository_revision where id=new.revision_id and repository_id=new.repository_id and tenant_id=new.tenant_id) then raise exception 'file revision belongs to another repository'; end if;
 if new.module_id is not null and not exists(select 1 from corpus.repository_module where id=new.module_id and repository_id=new.repository_id and tenant_id=new.tenant_id) then raise exception 'file module belongs to another repository'; end if;
 return new;
end $$;
create trigger repository_file_lineage before insert or update on corpus.repository_file for each row execute function corpus.check_repository_lineage();
create function temporal.admit_support(p_segment uuid,p_occurrence uuid,p_claim uuid,p_locator uuid,p_role text default 'supports') returns uuid language plpgsql security definer set search_path='' as $$
declare result uuid;
begin
 insert into evidence.segment_support(segment_id,event_occurrence_id,claim_id,locator_id,role) values(p_segment,p_occurrence,p_claim,p_locator,p_role) returning id into result;return result;
end $$;
create function temporal.withdraw_support(p_support uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 update evidence.segment_support set k_to=temporal.current_k() where id=p_support and tenant_id=util.current_tenant_id() and k_to is null;if not found then raise exception 'support not found';end if;
end $$;
revoke all on function temporal.admit_support(uuid,uuid,uuid,uuid,text),temporal.withdraw_support(uuid),corpus.check_receipt_tenant(),corpus.check_repository_lineage(),content.guard_summary_content(),content.check_summary_sources(),content.check_document_work() from public,anon,authenticated,service_role,pipeline_agent,verifier_agent,app_reader;
grant execute on function temporal.admit_support(uuid,uuid,uuid,uuid,text),temporal.withdraw_support(uuid) to executor_service;


